188	/*
189	 * Machinery to add the string loops to the existing ufuncs.
190	 */
191	
192	/*
193	 * This function replaces the strided loop with the passed in one,
194	 * and registers it with the given ufunc.
195	 */
196	static int
197	add_loop(PyObject *umath, const char *ufunc_name,
198	         PyArrayMethod_Spec *spec, PyArrayMethod_StridedLoop *loop)
199	{
200	    PyObject *name = PyUnicode_FromString(ufunc_name);
201	    if (name == nullptr) {
202	        return -1;
203	    }
204	    PyObject *ufunc = PyObject_GetItem(umath, name);
205	    Py_DECREF(name);
206	    if (ufunc == nullptr) {
207	        return -1;
208	    }
209	    spec->slots[0].pfunc = (void *)loop;
210	
211	    int res = PyUFunc_AddLoopFromSpec(ufunc, spec);
212	    Py_DECREF(ufunc);
213	    return res;
214	}
