318	 * This function is used for `compare_chararrays` and currently also void
319	 * comparisons (unstructured voids).  The first could probably be deprecated
320	 * and removed but is used by `np.char.chararray` the latter should also be
321	 * moved to the ufunc probably (removing the need for manual looping).
322	 *
323	 * The `rstrip` mechanism is presumably for some fortran compat, but the
324	 * question is whether it would not be better to have/use `rstrip` on such
325	 * an array first...
326	 *
327	 * NOTE: This function is also used for unstructured voids, this works because
328	 *       `npy_byte` is correct.
329	 */
330	NPY_NO_EXPORT PyObject *
331	_umath_strings_richcompare(
332	        PyArrayObject *self, PyArrayObject *other, int cmp_op, int rstrip)
333	{
334	    NpyIter *iter = nullptr;
335	    PyObject *result = nullptr;
336	
337	    char **dataptr = nullptr;
338	    npy_intp *strides = nullptr;
339	    npy_intp *countptr = nullptr;
340	    npy_intp size = 0;
341	
342	    PyArrayMethod_Context context = {};
343	    NpyIter_IterNextFunc *iternext = nullptr;
344	
345	    npy_uint32 it_flags = (
346	            NPY_ITER_EXTERNAL_LOOP | NPY_ITER_ZEROSIZE_OK |
347	            NPY_ITER_BUFFERED | NPY_ITER_GROWINNER);
348	    npy_uint32 op_flags[3] = {
349	            NPY_ITER_READONLY | NPY_ITER_ALIGNED,
350	            NPY_ITER_READONLY | NPY_ITER_ALIGNED,
351	            NPY_ITER_WRITEONLY | NPY_ITER_ALLOCATE | NPY_ITER_ALIGNED};
352	
353	    PyArrayMethod_StridedLoop *strided_loop = nullptr;
354	    NPY_BEGIN_THREADS_DEF;
355	
356	    if (PyArray_TYPE(self) != PyArray_TYPE(other)) {
357	        /*
358	         * Comparison between Bytes and Unicode is not defined in Py3K;
359	         * we follow.
360	         * TODO: This makes no sense at all for `compare_chararrays`, kept
361	         *       only under the assumption that we are more likely to deprecate
362	         *       than fix it to begin with.
363	         */
364	        Py_INCREF(Py_NotImplemented);
365	        return Py_NotImplemented;
366	    }
367	
368	    PyArrayObject *ops[3] = {self, other, nullptr};
369	    PyArray_Descr *descrs[3] = {nullptr, nullptr, PyArray_DescrFromType(NPY_BOOL)};
370	    /* TODO: ensuring native byte order is not really necessary for == and != */
371	    descrs[0] = NPY_DT_CALL_ensure_canonical(PyArray_DESCR(self));
372	    if (descrs[0] == nullptr) {
373	        goto finish;
374	    }
375	    descrs[1] = NPY_DT_CALL_ensure_canonical(PyArray_DESCR(other));
376	    if (descrs[1] == nullptr) {
377	        goto finish;
378	    }
379	
380	    /*
381	     * Create the iterator:
382	     */
383	    iter = NpyIter_AdvancedNew(
384	            3, ops, it_flags, NPY_KEEPORDER, NPY_SAFE_CASTING, op_flags, descrs,
385	            -1, nullptr, nullptr, 0);
386	    if (iter == nullptr) {
387	        goto finish;
388	    }
389	
390	    size = NpyIter_GetIterSize(iter);
391	    if (size == 0) {
392	        result = (PyObject *)NpyIter_GetOperandArray(iter)[2];
393	        Py_INCREF(result);
394	        goto finish;
395	    }
396	
397	    iternext = NpyIter_GetIterNext(iter, nullptr);
398	    if (iternext == nullptr) {
399	        goto finish;
400	    }
401	
402	    /*
403	     * Prepare the inner-loop and execute it (we only need descriptors to be
404	     * passed in).
405	     */
406	    context.descriptors = descrs;
407	
408	    dataptr = NpyIter_GetDataPtrArray(iter);
409	    strides = NpyIter_GetInnerStrideArray(iter);
410	    countptr = NpyIter_GetInnerLoopSizePtr(iter);
411	
412	    if (rstrip == 0) {
413	        /* NOTE: Also used for VOID, so can be STRING, UNICODE, or VOID: */
414	        if (descrs[0]->type_num != NPY_UNICODE) {
415	            strided_loop = get_strided_loop<false, npy_byte>(cmp_op);
416	        }
417	        else {
418	            strided_loop = get_strided_loop<false, npy_ucs4>(cmp_op);
419	        }
420	    }
421	    else {
422	        if (descrs[0]->type_num != NPY_UNICODE) {
423	            strided_loop = get_strided_loop<true, npy_byte>(cmp_op);
424	        }
425	        else {
426	            strided_loop = get_strided_loop<true, npy_ucs4>(cmp_op);
427	        }
428	    }
429	
430	    NPY_BEGIN_THREADS_THRESHOLDED(size);
431	
432	    do {
433	         /* We know the loop cannot fail */
434	         strided_loop(&context, dataptr, countptr, strides, nullptr);
435	    } while (iternext(iter) != 0);
436	
437	    NPY_END_THREADS;
438	
439	    result = (PyObject *)NpyIter_GetOperandArray(iter)[2];
440	    Py_INCREF(result);
441	
442	 finish:
443	    if (NpyIter_Deallocate(iter) < 0) {
444	        Py_CLEAR(result);
445	    }
446	    Py_XDECREF(descrs[0]);
447	    Py_XDECREF(descrs[1]);
448	    Py_XDECREF(descrs[2]);
449	    return result;
450	}
